// Basic extraction from HTML — Wellfound doesn't have a public API
const html = $input.first().json.data || '';
const jobMatches = [...html.matchAll(/data-job-id="(\d+)"[^>]*>[\s\S]*?<a[^>]+href="(\/jobs\/[^"]+)"[^>]*>([^<]+)<\/a>[\s\S]*?<span[^>]*>([^<]+)<\/span>/g)];
if (!jobMatches.length) return [{ json: { _source: 'wellfound', _empty: true } }];
return jobMatches.map(m => ({ json: { _source: 'wellfound', job_id: m[1], job_url: 'https://wellfound.com' + m[2], job_title: m[3].trim(), company: m[4].trim() } }));

const html = $input.first().json.data || '';
const matches = [...html.matchAll(/href="(\/jobs\/[^"]+)"[^>]*>\s*([^<]+)<\/a>/g)];
if (!matches.length) return [{ json: { _source: 'yc', _empty: true } }];
return matches.slice(0, 50).map(m => ({ json: { _source: 'yc', job_url: 'https://www.workatastartup.com' + m[1], job_title: m[2].trim() } }));

const html = $input.first().json.data || '';
const matches = [...html.matchAll(/href="(\/jobs\/[^"]+)"[^>]*>([^<]+)<\/a>/g)];
if (!matches.length) return [{ json: { _source: 'otta', _empty: true } }];
return matches.slice(0, 50).map(m => ({ json: { _source: 'otta', job_url: 'https://app.otta.com' + m[1], job_title: m[2].trim() } }));

const normalizedJobs = [];
const seen = new Set();

for (const item of $input.all()) {
  const d = item.json;
  if (d._empty) continue;

  let job = {
    job_title: '', company: '', job_url: '', source: '',
    location_text: '', salary: '', description: '', posted_date: '', tags: '', job_id: ''
  };

  const src = d._source || '';

  if (src === 'remoteok') {
    job.source = 'Remote OK';
    job.job_title = d.position || d.title || '';
    job.company = d.company || '';
    job.job_url = d.url || (d.id ? `https://remoteok.com/jobs/${d.id}` : '');
    job.location_text = d.location || 'Worldwide';
    job.salary = d.salary_min ? `$${d.salary_min}-$${d.salary_max}` : (d.salary || '');
    job.description = d.description || d.body || '';
    job.posted_date = d.date || '';
    job.tags = Array.isArray(d.tags) ? d.tags.join(', ') : (d.tags || '');

  } else if (src === 'remotive') {
    job.source = 'Remotive';
    job.job_title = d.title || '';
    job.company = d.company_name || '';
    job.job_url = d.url || '';
    job.location_text = d.candidate_required_location || 'Worldwide';
    job.salary = d.salary || '';
    job.description = d.description || '';
    job.posted_date = d.publication_date || '';
    job.tags = Array.isArray(d.tags) ? d.tags.join(', ') : '';

  } else if (src === 'himalayas') {
    job.source = 'Himalayas';
    job.job_title = d.title || '';
    job.company = d.companyName || d.company || '';
    job.job_url = d.applicationLink || d.url || '';
    job.location_text = Array.isArray(d.locationRestrictions) ? d.locationRestrictions.join(', ') : (d.location || 'Worldwide');
    job.salary = d.salary || (d.minAnnualSalary ? `$${d.minAnnualSalary}` : '');
    job.description = d.description || '';
    job.posted_date = d.publishedAt || '';
    job.tags = Array.isArray(d.categories) ? d.categories.join(', ') : '';

  } else if (src === 'wellfound') {
    job.source = 'Wellfound';
    job.job_title = d.job_title || d.title || '';
    job.company = d.company || '';
    job.job_url = d.job_url || d.url || '';
    job.location_text = d.location || 'Remote';
    job.description = d.description || '';
    job.tags = d.tags || '';

  } else if (src === 'yc') {
    job.source = 'YC Work at a Startup';
    job.job_title = d.job_title || d.title || '';
    job.company = d.company || '';
    job.job_url = d.job_url || '';
    job.location_text = d.location || 'Remote';
    job.description = d.description || '';

  } else if (src === 'otta') {
    job.source = 'Otta';
    job.job_title = d.job_title || d.title || '';
    job.company = d.company || '';
    job.job_url = d.job_url || '';
    job.location_text = d.location || 'Remote';
    job.description = d.description || '';

  } else {
    // RSS generic (WWR, Dynamite)
    const srcMap = { weworkremotely: 'We Work Remotely', dynamitejobs: 'Dynamite Jobs' };
    job.source = srcMap[src] || src;
    job.job_title = d.title || '';
    job.company = d['dc:creator'] || d.author || d.company || '';
    job.job_url = d.link || d.guid || '';
    job.location_text = d.location || 'Remote';
    job.salary = d.salary || '';
    job.description = d['content:encoded'] || d.content || d.description || d.summary || '';
    job.posted_date = d.pubDate || d.published || '';
    job.tags = Array.isArray(d.categories) ? d.categories.join(', ') : (d.categories || '');
  }

  // Clean HTML from description
  job.description = job.description.replace(/<[^>]*>/g, ' ').replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim();
  if (job.description.length > 4000) job.description = job.description.substring(0, 4000);

  job.job_id = job.job_url.trim();
  const dedupeKey = job.job_url || `${job.company}||${job.job_title}`;

  if (job.job_title && job.job_url && !seen.has(dedupeKey)) {
    seen.add(dedupeKey);
    normalizedJobs.push({ json: job });
  }
}

return normalizedJobs;

// Build set of existing job URLs and company+title keys from the Sheets read
const existingUrls = new Set();
const existingKeys = new Set();

try {
  const sheetItems = $('Get Existing Job URLs').all();
  for (const item of sheetItems) {
    if (item.json.job_url) existingUrls.add(item.json.job_url.trim());
    if (item.json.company && item.json.job_title) {
      existingKeys.add(`${item.json.company}||${item.json.job_title}`.toLowerCase());
    }
  }
} catch(e) { /* Sheet may be empty on first run */ }

const newJobs = [];
for (const item of $input.all()) {
  const job = item.json;
  const urlKey = (job.job_url || '').trim();
  const titleKey = `${job.company}||${job.job_title}`.toLowerCase();
  if (!existingUrls.has(urlKey) && !existingKeys.has(titleKey)) {
    existingUrls.add(urlKey);
    existingKeys.add(titleKey);
    newJobs.push({ json: job });
  }
}

return newJobs;

const REJECT_PHRASES = [
  'us only','usa only','us residents only','united states only','us-based only',
  'must be based in the us','must be based in the united states',
  'must live in the us','must reside in the us',
  'canada only','uk only','eu only','europe only','european union only',
  'australia only','new zealand only','north america only',
  'must be authorized to work in','authorized to work in the us',
  'requires us work authorization','work authorization required',
  'local work permit required','work permit required',
  'must work us hours','must overlap us business hours',
  'hybrid','on-site','onsite','in-office','office required',
  'remote within the us','remote us only','remote in the us',
  'remote within country only','remote within one country',
  'fixed est hours','fixed pst hours','fixed cst hours','fixed cet hours'
];

const KEEP_SIGNALS = [
  'worldwide','work from anywhere','anywhere in the world','global remote',
  'globally distributed','fully distributed','distributed team',
  'all timezones','any timezone','async','asynchronous',
  'apac','asia pacific','international contractors',
  'contractor','b2b','freelance','independent contractor',
  'deel','remote.com','oyster','eor','employer of record',
  'remote first','remote-first'
];

const kept = [];
const rejected = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.job_title} ${job.description} ${job.location_text} ${job.tags}`.toLowerCase();

  let rejectPhrase = null;
  for (const p of REJECT_PHRASES) {
    if (text.includes(p)) { rejectPhrase = p; break; }
  }

  if (rejectPhrase) {
    rejected.push({ json: { ...job, reject_reason: `Hard filter: "${rejectPhrase}"`, filter_stage: 'taiwan_hard_filter' } });
  } else {
    // Flag keep signals for later scoring
    const signals = KEEP_SIGNALS.filter(s => text.includes(s));
    kept.push({ json: { ...job, keep_signals: signals.join(', ') } });
  }
}

return [kept, rejected];

