let aiResult = {};
try {
  const content = $json.choices[0].message.content;
  aiResult = JSON.parse(content);
} catch(e) {
  aiResult = {
    taiwan_eligible: 'unclear',
    reason: 'AI parse error',
    location_risk: 'medium',
    timezone_risk: 'medium',
    contractor_possible: 'unclear',
    decision: 'manual_check'
  };
}

// Merge AI result with original job data from the batch
const originalJob = $('Split for AI Check').first().json;

return {
  json: {
    ...originalJob,
    taiwan_eligible: aiResult.taiwan_eligible,
    taiwan_reason: aiResult.reason,
    location_risk: aiResult.location_risk,
    timezone_risk: aiResult.timezone_risk,
    contractor_possible: aiResult.contractor_possible,
    ai_decision: aiResult.decision
  }
};

const ASYNC_STRONG = ['fully async','100% async','async-first','async first'];
const ASYNC_MEDIUM = ['async','asynchronous','flexible hours','flexible schedule','no meetings','low meeting','work across time zones','distributed team','remote first','remote-first'];
const ASYNC_REJECT = ['strict 9 to 5','9-to-5','fixed us hours','fixed est hours','fixed pst hours','fixed cet hours','daily standup required','must overlap full business day','daily live calls required','real-time availability required'];

const kept = [];
const rejected = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.description} ${job.job_title} ${job.tags} ${job.keep_signals || ''}`.toLowerCase();

  let asyncRejectPhrase = null;
  for (const p of ASYNC_REJECT) {
    if (text.includes(p)) { asyncRejectPhrase = p; break; }
  }

  if (asyncRejectPhrase && job.location_risk !== 'low') {
    rejected.push({ json: { ...job, reject_reason: `Async reject: "${asyncRejectPhrase}"`, filter_stage: 'async_filter' } });
    continue;
  }

  let async_level = 'unknown';
  if (ASYNC_STRONG.some(p => text.includes(p))) async_level = 'high';
  else if (ASYNC_MEDIUM.some(p => text.includes(p))) async_level = 'medium';
  else if (asyncRejectPhrase) async_level = 'low';
  else async_level = 'medium'; // default for async remote jobs

  kept.push({ json: { ...job, async_level } });
}

return [kept, rejected];

const ROLE_PRIMARY = [
  'data analyst','data scientist','junior data scientist','business intelligence',
  'bi analyst','marketing analyst','performance marketing','growth analyst',
  'ai marketing','ai automation','ai workflow','martech analyst',
  'creative strategist','marketing data','analytics engineer','revenue analyst'
];
const ROLE_ADJACENT = [
  'product analyst','operations analyst','reporting analyst','insights analyst',
  'automation specialist','digital marketing','seo analyst','ppc analyst',
  'growth hacker','ecommerce analyst','crm analyst','customer success analyst',
  'machine learning','ml engineer','ai engineer','data engineer'
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.job_title} ${job.description} ${job.tags}`.toLowerCase();

  // --- Taiwan eligibility score (40 pts max) ---
  let taiwan_score = 0;
  const eligText = `${job.taiwan_eligible} ${job.taiwan_reason} ${job.keep_signals || ''} ${job.location_text}`.toLowerCase();
  if (job.taiwan_eligible === 'yes') {
    if (['worldwide','work from anywhere','global remote','contractor','deel','oyster','remote.com','eor'].some(k => eligText.includes(k))) taiwan_score = 40;
    else if (eligText.includes('apac')) taiwan_score = 30;
    else taiwan_score = 20;
  } else if (job.taiwan_eligible === 'unclear') {
    taiwan_score = 20;
  } else {
    taiwan_score = 0;
  }

  // --- Async fit score (25 pts max) ---
  let async_score = 0;
  if (job.async_level === 'high') async_score = 25;
  else if (job.async_level === 'medium') {
    const t = `${job.description} ${job.tags}`.toLowerCase();
    if (t.includes('flexible hours') || t.includes('flexible schedule')) async_score = 20;
    else if (t.includes('distributed team')) async_score = 15;
    else async_score = 10;
  } else async_score = 5;

  // --- Role fit score (25 pts max) ---
  let role_score = 0;
  let role_category = 'other';
  if (ROLE_PRIMARY.some(r => text.includes(r))) {
    role_score = 25;
    role_category = ROLE_PRIMARY.find(r => text.includes(r)) || 'primary';
  } else if (ROLE_ADJACENT.some(r => text.includes(r))) {
    role_score = 15;
    role_category = ROLE_ADJACENT.find(r => text.includes(r)) || 'adjacent';
  } else {
    role_score = 5;
  }

  // --- Salary score (25 pts max) ---
  let salary_score = 0;
  const salaryStr = `${job.salary} ${job.description}`.toLowerCase();
  const salaryMatch = salaryStr.match(/(\$|usd)\s*([\d,]+)(?:k|,000)?(?:\s*-\s*(\$|usd)?\s*([\d,]+)(?:k|,000)?)?/i);
  if (salaryMatch) {
    let amount = parseFloat(salaryMatch[2].replace(',', ''));
    if (amount < 1000) amount *= 1000; // convert k
    const monthly = amount / 12;
    if (monthly >= 5000) salary_score = 25;
    else if (monthly >= 3000) salary_score = 15;
    else salary_score = 10;
  } else if (salaryStr.includes('competitive') || salaryStr.includes('salary')) {
    salary_score = 10;
  }

  const total_score = taiwan_score + async_score + role_score + salary_score;

  // --- Why it fits Jerry ---
  const why_parts = [];
  if (taiwan_score >= 30) why_parts.push('Strong Taiwan eligibility (worldwide/contractor)');
  else if (taiwan_score >= 20) why_parts.push('Possible Taiwan eligibility');
  if (async_score >= 20) why_parts.push('Fully async or flexible hours');
  if (role_score >= 20) why_parts.push(`Strong role match: ${role_category}`);
  if (salary_score >= 15) why_parts.push('Salary meets target threshold');
  const why_good_fit = why_parts.join(' | ') || 'Needs manual review';

  // --- Final decision ---
  let decision;
  if (job.taiwan_eligible === 'no' || job.location_risk === 'high' || total_score < 70) {
    decision = 'reject';
  } else if (job.taiwan_eligible === 'yes' && total_score >= 85 && job.async_level !== 'low' && job.location_risk === 'low') {
    decision = 'apply_now';
  } else if (job.taiwan_eligible === 'unclear' && total_score >= 70) {
    decision = 'manual_check';
  } else if (total_score >= 70) {
    decision = 'apply_now';
  } else {
    decision = 'reject';
  }

  results.push({ json: {
    ...job,
    taiwan_score, async_score, role_score, salary_score,
    score: total_score, role_category, why_good_fit, decision,
    date_found: new Date().toISOString().split('T')[0],
    application_status: 'new', notes: ''
  }});
}

return results;

