// Collect all filtered jobs (score >= 70) from the Filtered Jobs sheet save node
let allJobs = [];
try { allJobs = $('Save to Filtered Jobs Sheet').all().map(i => i.json); } catch(e) {}

if (!allJobs.length) {
  return [{ json: { digest: 'No new Taiwan-eligible async remote jobs found today.', job_count: 0 } }];
}

// Sort by score descending
allJobs.sort((a, b) => (b.score || 0) - (a.score || 0));

const top = allJobs.slice(0, 10);
const manual = allJobs.filter(j => j.decision === 'manual_check');
const urgent = allJobs.filter(j => j.score >= 85);

// Count rejections by type (from Rejected sheet saves)
let rejectedItems = [];
try { rejectedItems = $('Save to Rejected Sheet').all().map(i => i.json); } catch(e) {}
try { rejectedItems = rejectedItems.concat($('Save Hard-Rejected to Sheet').all().map(i => i.json)); } catch(e) {}

const rejCount = {
  us_only: rejectedItems.filter(r => (r.reason || '').toLowerCase().includes('us')).length,
  eu_only: rejectedItems.filter(r => (r.reason || '').toLowerCase().includes('eu') || (r.reason || '').toLowerCase().includes('europe')).length,
  hybrid: rejectedItems.filter(r => (r.reason || '').toLowerCase().includes('hybrid')).length,
  timezone: rejectedItems.filter(r => (r.reason || '').toLowerCase().includes('timezone') || (r.reason || '').toLowerCase().includes('hours')).length,
  total: rejectedItems.length
};

let digest = `🇹🇼 Daily Taiwan Eligible Async Remote Jobs\n`;
digest += `📅 ${new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}\n`;
digest += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n`;

if (urgent.length > 0) {
  digest += `🔥 INSTANT ALERT: ${urgent.length} job(s) scored 85+\n\n`;
}

digest += `📋 TOP JOBS TODAY (${allJobs.length} passed all filters)\n\n`;

top.forEach((job, i) => {
  digest += `${i + 1}. ${job.job_title}\n`;
  digest += `   Company: ${job.company}\n`;
  digest += `   Score: ${job.score}/100 ${job.score >= 85 ? '🔥' : job.score >= 75 ? '⭐' : ''}\n`;
  digest += `   Taiwan Eligible: ${job.taiwan_eligible?.toUpperCase()} | ${job.taiwan_reason}\n`;
  digest += `   Async Level: ${job.async_level}\n`;
  digest += `   Timezone Risk: ${job.timezone_risk}\n`;
  digest += `   Salary: ${job.salary || 'Not listed'}\n`;
  digest += `   Why it fits Jerry: ${job.why_good_fit}\n`;
  digest += `   Apply: ${job.job_url}\n\n`;
});

if (manual.length > 0) {
  digest += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  digest += `🔍 MANUAL CHECK (${manual.length} jobs — high score, unclear eligibility)\n\n`;
  manual.forEach((job, i) => {
    digest += `${i + 1}. ${job.job_title} @ ${job.company} — Score: ${job.score} | ${job.taiwan_reason}\n`;
    digest += `   ${job.job_url}\n\n`;
  });
}

digest += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
digest += `🚫 REJECTED SUMMARY (${rejCount.total} total rejected today)\n`;
digest += `   US only: ${rejCount.us_only}\n`;
digest += `   EU/Europe only: ${rejCount.eu_only}\n`;
digest += `   Hybrid/Onsite: ${rejCount.hybrid}\n`;
digest += `   Timezone risk: ${rejCount.timezone}\n`;

return [{ json: { digest, job_count: allJobs.length, urgent_count: urgent.length } }];
